#!/usr/bin/env bash
# Golden-output check for a variant: build its CLI jar, run `analyze` over the fixture folder and diff the generated
# reports against the stored golden output (generated by variant A). Volatile parts (dates, timings, random ids)
# are normalized before the diff. Usage:
#   scripts/golden.sh a --store      # build variant A, generate and store golden/ (do once)
#   scripts/golden.sh b              # build variant B, generate and compare with golden/
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
V="${1:?variant}"; MODE="${2:-}"
SRC="$ROOT/variants/$V"
FIXTURE="${GOLDEN_FIXTURE:-$ROOT/variants/a/common}"   # a mid-size Java tree with history-free files; override with GOLDEN_FIXTURE
OUT="$ROOT/work/golden-$V"
GOLDEN="$ROOT/golden"
rm -rf "$OUT"; mkdir -p "$OUT/src"
cp -R "$FIXTURE/." "$OUT/src/"
( cd "$SRC" && mvn -q -o install -DskipTests )
JAR="$SRC/cli/target/cli-1.0-jar-with-dependencies.jar"
( cd "$OUT/src" && SOKRATES_OFFLINE=1 java -jar "$JAR" init -srcRoot . -confFile "$OUT/_sokrates/config.json" >/dev/null \
  && SOKRATES_OFFLINE=1 java -jar "$JAR" generateReports -confFile "$OUT/_sokrates/config.json" -outputFolder "$OUT/reports" -date 2025-09-20 -timeout 1200 >/dev/null )
# normalize: unzip data.zip, drop timing/date noise
mkdir -p "$OUT/norm"
( cd "$OUT/reports/data" && unzip -q -o data.zip -d "$OUT/norm/data" )
cp -R "$OUT/reports/html" "$OUT/norm/html"
find "$OUT/norm" -type f \( -name '*.html' -o -name '*.json' -o -name '*.txt' \) -print0 | xargs -0 sed -i '' -E \
  -e 's/[0-9]{4}-[0-9]{2}-[0-9]{2}( [0-9:]{8})?/DATE/g' \
  -e 's/"analysisStartTimeMs" ?: ?[0-9]+/"analysisStartTimeMs": T/g' \
  -e 's/[0-9]+ ms/N ms/g' -e 's/[0-9]+(\.[0-9]+)? s(ec)?\b/N s/g'
rm -f "$OUT/norm/data/analysisStats.json" "$OUT/norm/data/executionStats.json" 2>/dev/null || true
if [ "$MODE" = "--store" ]; then
  rm -rf "$GOLDEN"; cp -R "$OUT/norm" "$GOLDEN"; echo "golden output stored in $GOLDEN"
else
  [ -d "$GOLDEN" ] || { echo "no golden output yet: run scripts/golden.sh a --store"; exit 1; }
  if diff -r -q "$GOLDEN" "$OUT/norm" >"$OUT/diff.txt"; then echo "golden output identical"; else echo "DIFFERENCES (see $OUT/diff.txt):"; head -40 "$OUT/diff.txt"; exit 1; fi
fi
